<template>
  <section class="privacy-rights" aria-label="个人信息权利申请"><header><span>YOUR RIGHTS</span><h2>个人信息权利申请</h2><p>申请与回复仅本人及有权限的平台处理人员可见。请描述必要事项，不填写密码、完整证件号码或他人的资料。</p></header><p v-if="error" class="rights-message" role="alert">{{ error }}</p><p v-if="notice" class="rights-message success" role="status">{{ notice }}</p>
    <form v-if="token" @submit.prevent="submit"><label>需要办理的事项<select v-model="type" :disabled="saving"><option v-for="(label, key) in types" :key="key" :value="key">{{ label }}</option></select></label><label>具体事项<textarea v-model="detail" maxlength="2000" rows="5" required :disabled="saving" placeholder="说明需要查阅、更正或删除的信息，以及你期望的处理方式。" /></label><p v-if="type === 'close'" class="rights-close-note">注销由平台核对后办理。担任团长时，可先办理移交或说明实际困难，平台将协助核对；依法需要保留的记录将说明范围与依据。</p><button type="submit" class="rights-submit" :disabled="saving">{{ saving ? '正在提交…' : '私密提交申请' }}</button></form><button v-else class="rights-submit" type="button" @click="login">登录后提交申请</button>
    <section v-if="token" class="rights-history"><h3>我的申请与回复<button type="button" @click="load" :disabled="loading || saving">刷新</button></h3><p v-if="loading" class="rights-hint" role="status">正在读取申请…</p><p v-else-if="!requests.length" class="rights-hint">你还没有提交过权利申请。</p><article v-for="item in requests" :key="item.id" class="rights-record"><span>{{ statuses[item.status] || item.status }} · #{{ item.id }}</span><h4>{{ types[item.type] || item.type }}</h4><small>{{ date(item.createdAt) }}</small><p>{{ item.detail }}</p><div v-if="item.response" class="rights-response"><b>平台回复</b><p>{{ item.response }}</p></div></article></section>
  </section>
</template>
<script setup>
import { ref, watch } from 'vue';
import { useRouter } from 'vue-router';
import { useClubSession } from '../useClubSession';
const types = { access: '查阅个人信息', copy: '复制个人信息', correct: '更正或补充', delete: '删除个人信息', withdraw: '撤回同意', close: '注销账号', other: '其他权利或投诉' };
const statuses = { pending: '已提交', processing: '处理中', needs_info: '待你补充', completed: '已回复办结', rejected: '未予办理' };
const router = useRouter(), type = ref('access'), detail = ref(''), requests = ref([]), loading = ref(false), saving = ref(false), error = ref(''), notice = ref('');
function reset() { detail.value = ''; requests.value = []; loading.value = false; saving.value = false; error.value = ''; notice.value = ''; }
const { token, request, capture, current } = useClubSession(reset, () => 'privacy-rights');
function login() { localStorage.setItem('marathon_return_after_login', '/legal/rights'); router.push('/mine'); }
function date(value) { return String(value || '').slice(0, 10); }
async function load() { if (!token.value) return; const stamp = capture(); loading.value = true; error.value = ''; try { const data = await request('/me/privacy-requests'); if (current(stamp)) requests.value = data.requests || []; } catch (err) { if (!err.stale && current(stamp)) { if ([401, 403].includes(err.status)) { requests.value = []; detail.value = ''; } error.value = err.message; } } finally { if (current(stamp)) loading.value = false; } }
async function submit() { if (saving.value) return; const stamp = capture(); if (!current(stamp) || !token.value) return; const text = detail.value.trim(); if (!text) { error.value = '请填写需要办理的具体事项。'; return; } saving.value = true; error.value = ''; notice.value = ''; try { await request('/me/privacy-requests', { method: 'POST', body: JSON.stringify({ type: type.value, detail: text }) }); if (!current(stamp)) return; detail.value = ''; notice.value = '申请已私密提交，请在下方查看回复。提交注销或删除申请不会立即删除账号。'; await load(); } catch (err) { if (!err.stale && current(stamp)) error.value = err.message; } finally { if (current(stamp)) saving.value = false; } }
watch(token, load, { immediate: true });
</script>
<style scoped>
.privacy-rights{margin-top:28px;border:1px solid #e9ecf1;border-radius:17px;background:#fff;padding:34px 38px;overflow-wrap:anywhere}.privacy-rights header>span{font-size:10px;letter-spacing:2px;color:#b48a99}.privacy-rights h2{font-size:23px;margin:15px 0}.privacy-rights header p{font-size:12px;line-height:1.95;color:#8590a1;margin:12px 0 24px}.privacy-rights form{margin-top:24px}.privacy-rights label{display:grid;gap:11px;margin:19px 0;color:#677487;font-size:12px;line-height:1.8}.privacy-rights select,.privacy-rights textarea{border:1px solid #e2e7ed;background:#f8f9fb;border-radius:9px;min-height:46px;width:100%;min-width:0;padding:12px;font:inherit;line-height:1.9;color:#525e71;box-sizing:border-box}.rights-submit{background:#ff0a30;color:white;font-size:12px;min-height:45px;padding:12px 21px;border-radius:9px;font-weight:600}.rights-message{font-size:12px;line-height:1.9;padding:15px;border:1px solid #f2dfe6;border-radius:10px;background:#fff5f8;color:#a3647d}.rights-message.success{color:#527e6a;background:#eff8f3;border-color:#e1eee5}.rights-history{padding-top:25px;border-top:1px solid #e9edf2;margin-top:30px}.rights-history h3{display:flex;align-items:center;justify-content:space-between;gap:12px;font-size:16px}.rights-history h3 button{color:#ab8295;font-size:11px;min-height:44px}.rights-hint{color:#939cab;font-size:12px;line-height:1.9}.rights-record{border:1px solid #e6ebf0;border-radius:11px;padding:20px;margin-top:18px}.rights-record>span{font-size:10px;color:#ab748b;line-height:1.9}.rights-record h4{font-size:15px;margin:10px 0}.rights-record>small{font-size:10px;color:#a2aab6}.rights-record p{font-size:12px;line-height:1.95;color:#7a8596;white-space:pre-wrap;margin:16px 0 0}.rights-response{padding:17px;background:#fcf7f9;border-radius:9px;margin-top:18px}.rights-response b{font-size:11px;color:#a98293;font-weight:500}.rights-response p{color:#987b89;margin-top:9px}.rights-close-note{background:#fff9f2;color:#9b7c66;font-size:11px;line-height:1.95;padding:14px;border-radius:9px}.privacy-rights button:disabled{opacity:.5}.privacy-rights input:focus-visible,.privacy-rights select:focus-visible,.privacy-rights textarea:focus-visible,.privacy-rights button:focus-visible{outline:2px solid #ef7897;outline-offset:3px}@media(max-width:700px){.privacy-rights{padding:26px 21px;border-radius:14px}.privacy-rights h2{font-size:22px}}
</style>
